// C++ 'inline' keyword: A hint to the compiler
// Compiler may ignore this if the function is too large.
inline int square(int x) {
    return x * x;
}

// GCC/Clang: Forcing the heuristic decision (Mandatory Inlining)
// Used when performance gain overrides code size increase.
__attribute__((always_inline))
static void critical_section() {
    // ... minimal code
}

// GCC/Clang: Preventing the heuristic decision (No Inlining)
// Useful for large functions or ensuring call stack visibility for debugging.
__attribute__((noinline))
void heavy_initialization(Config c) {
    // 50+ lines of initialization code
}

// Implicit Size Heuristic:
// Low cost (very likely inline, even without 'inline')
int get_version() { return 2; }

// High cost (less likely inline unless -O3 or forced)
int complex_calc(Data d) {
    if (d.valid) return d.val * d.scale;
    // ... several branches
    return 0;
}
